'use strict';

const fs = require('fs');

/**
 * Parse a transcript file and return { gross, net, output } token sums.
 *
 * gross  — sum of all token fields on every line with a `usage` object.
 * net    — gross minus tokens on lines where source === "mcp_tool".
 * output — sum of output_tokens only, across every line with `usage`.
 */
function parseTranscript(filePath) {
  const lines = fs.readFileSync(filePath, 'utf8').split('\n');
  let gross = 0;
  let mcpOverhead = 0;
  let output = 0;

  for (const raw of lines) {
    const line = raw.trim();
    if (!line) continue;

    let obj;
    try {
      obj = JSON.parse(line);
    } catch {
      // Not valid JSON — skip silently.
      continue;
    }

    const usage = obj && obj.usage;
    if (!usage || typeof usage !== 'object') continue;

    const inputTokens    = usage.input_tokens    || 0;
    const outputTokens   = usage.output_tokens   || 0;
    const cacheRead      = usage.cache_read_input_tokens   || 0;
    const cacheCreation  = usage.cache_creation_input_tokens || 0;

    const lineTotal = inputTokens + outputTokens + cacheRead + cacheCreation;

    gross += lineTotal;
    output += outputTokens;

    if (obj.source === 'mcp_tool') {
      mcpOverhead += lineTotal;
    }
  }

  return { gross, net: gross - mcpOverhead, output };
}

/**
 * Compute ON/OFF token-usage ratios from two transcript files.
 *
 * @param {string} onTranscript  — path to the orchestrator-ON transcript (JSONL).
 * @param {string} offTranscript — path to the orchestrator-OFF transcript (JSONL).
 * @returns {{ gross: number|null, net: number|null, output: number|null }}
 */
function computeRatio(onTranscript, offTranscript) {
  const on  = parseTranscript(onTranscript);
  const off = parseTranscript(offTranscript);

  function ratio(onVal, offVal) {
    if (offVal === 0) return null;
    return Math.round((onVal / offVal) * 10000) / 10000;
  }

  return {
    gross:  ratio(on.gross,  off.gross),
    net:    ratio(on.net,    off.net),
    output: ratio(on.output, off.output),
  };
}

module.exports = { computeRatio };

