node -e "
const { computeRatio } = require('./bench/sandbox/compute-ratio-ht.js');
const fs = require('fs');
const path = require('path');

// Example 1 — simple, no MCP
const on1 = path.join(__dirname, '/tmp/on1.jsonl');
const off1 = path.join(__dirname, '/tmp/off1.jsonl');
fs.writeFileSync(on1, JSON.stringify({role:'assistant',usage:{input_tokens:100,output_tokens:50,cache_read_input_tokens:0,cache_creation_input_tokens:0}}) + '\n' +
                  JSON.stringify({role:'assistant',usage:{input_tokens:80,output_tokens:30,cache_read_input_tokens:0,cache_creation_input_tokens:0}}) + '\n');
fs.writeFileSync(off1, JSON.stringify({role:'assistant',usage:{input_tokens:200,output_tokens:100,cache_read_input_tokens:0,cache_creation_input_tokens:0}}) + '\n');

console.log('Example 1:', JSON.stringify(computeRatio(on1, off1)));
// Expected: { gross: 0.8667, net: 0.8667, output: 0.8 }

// Example 2 — with MCP plumbing
const on2 = path.join(__dirname, '/tmp/on2.jsonl');
const off2 = path.join(__dirname, '/tmp/off2.jsonl');
fs.writeFileSync(on2, JSON.stringify({role:'assistant',usage:{input_tokens:50,output_tokens:40,cache_read_input_tokens:2000,cache_creation_input_tokens:0}}) + '\n' +
                  JSON.stringify({role:'assistant',source:'mcp_tool',usage:{input_tokens:10,output_tokens:5,cache_read_input_tokens:1800,cache_creation_input_tokens:0}}) + '\n');
fs.writeFileSync(off2, JSON.stringify({role:'assistant',usage:{input_tokens:200,output_tokens:80,cache_read_input_tokens:200,cache_creation_input_tokens:0}}) + '\n');

console.log('Example 2:', JSON.stringify(computeRatio(on2, off2)));
// Expected: { gross: 8.1354, net: 4.3542, output: 0.5625 }

// Edge: zero denominator
const empty = path.join(__dirname, '/tmp/empty.jsonl');
fs.writeFileSync(empty, '');
console.log('Zero denom:', JSON.stringify(computeRatio(on2, empty)));
// Expected: { gross: null, net: null, output: null }

// Edge: invalid JSON lines mixed in
const dirty = path.join(__dirname, '/tmp/dirty.jsonl');
fs.writeFileSync(dirty, 'not json\n' + JSON.stringify({role:'assistant',usage:{input_tokens:100,output_tokens:50,cache_read_input_tokens:0,cache_creation_input_tokens:0}}) + '\n' + '{broken\n');
console.log('Dirty lines:', JSON.stringify(computeRatio(dirty, off1)));
// Should behave like example 1 but with half the values

// Edge: missing usage sub-fields
const partial = path.join(__dirname, '/tmp/partial.jsonl');
fs.writeFileSync(partial, JSON.stringify({role:'assistant',usage:{output_tokens:30}}) + '\n');
console.log('Partial usage:', JSON.stringify(computeRatio(partial, empty)));
// output=30, gross=30, net=30, all ratios null

// Cleanup
fs.unlinkSync(on1); fs.unlinkSync(off1); fs.unlinkSync(on2); fs.unlinkSync(off2);
fs.unlinkSync(empty); fs.unlinkSync(dirty); fs.unlinkSync(partial);
"

